// THE DELIVERY GATE ON MAIN — did the commit that just landed change a pack's
// shipping content without moving that pack's version?
//
// `pack-version-bumped` already asks that question, and on a branch it answers
// it correctly: against its own merge base the change moved the version, and
// green is the truth. What no branch can see is the OTHER branch. Two cut from
// the same main both bump to the same next number, both go green, and `pack.mjs`
// auto-merges because the two sides wrote identical bytes — so the second commit
// lands on main having edited five shipping files while the version sits exactly
// where its parent left it. Members that already converged hold the first tree
// under that number, `planPackUpdates` reads `installed >= canon`, and the second
// change reaches nobody, permanently (#1482: #1466's janitor widening swept the
// whole fleet as the old code).
//
// So the question is asked again where both branches are finally visible: on
// main, against the commit main was at before this push. Same rule, different
// base — a branch is judged against where it forked, a push to main against what
// main actually held. The base is the push event's `before` sha where CI supplies
// one (a push can carry several commits), else the parent.
//
// It is not the whole work sweep. A member's maintenance merges and this repo's
// own automation land here too, and the branch-shaped rules (a task, an issue, a
// session behind the change) have no answer on a squashed merge commit. Delivery
// is the one question whose answer is still meaningful after the squash.
import { execFileSync } from 'node:child_process';
import { realpathSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import rule from './workRules/pack-version-bumped.mjs';

const git = (root, ...args) => {
  try { return execFileSync('git', args, { cwd: root, encoding: 'utf8' }); } catch { return null; }
};

const at = (root, ref, file) => git(root, 'show', `${ref}:${file}`);

// The commit main stood at before this push: the event's `before` where it names
// a commit this checkout can resolve, else HEAD's parent. GitHub writes an
// all-zero `before` for a created ref and a stale one after a force-push, and
// either would judge against nothing — so an unresolvable sha falls back rather
// than failing, and a HEAD with no parent has nothing to judge at all.
export function resolveBefore(root, { before = null } = {}) {
  const resolvable = (ref) => (ref && git(root, 'rev-parse', '--verify', '--quiet', `${ref}^{commit}`) ? ref : null);
  return resolvable(before) || resolvable('HEAD^');
}

// The work context the rule reads, over two commits instead of a working tree.
export function contextBetween(root, base, head = 'HEAD') {
  const changed = (git(root, 'diff', '--name-only', `${base}..${head}`) || '').split('\n').filter(Boolean);
  return { changedFiles: changed, read: (f) => at(root, head, f), readBase: (f) => at(root, base, f) };
}

export function judge(root, { before = null } = {}) {
  const base = resolveBefore(root, { before });
  if (!base) return { base: null, findings: [] };
  return { base, findings: rule.run(contextBetween(root, base)) };
}

// CI runs this on every push to main: `node .claudinite/local/packs/canon-curation/pack-delivery-on-main.mjs`.
//   exit 0 — every pack this push edited moved its version (or it edited none)
//   exit 1 — a pack's content landed under the version main already published
if (process.argv[1] && realpathSync(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const root = process.argv[2] || process.cwd();
  const { base, findings } = judge(root, { before: process.env.GITHUB_EVENT_BEFORE || null });
  if (!base) {
    console.log('pack-delivery-on-main: no previous commit to judge against — nothing to say.');
    process.exit(0);
  }
  if (findings.length) {
    console.error(`pack-delivery-on-main: FAIL — ${findings.length} pack(s) landed content that no member will be sent (vs ${base}):`);
    for (const f of findings) console.error(`  - ${f.file}: ${f.what}\n    ${f.fix}`);
    console.error('\nThis is what two branches racing to the same version looks like once they are both on main.'
      + ' Cut a fresh version for the pack, with its VERSIONS.md row, so the content that landed here is delivered.');
    process.exit(1);
  }
  console.log(`pack-delivery-on-main: OK — every pack this push edited moved its version (vs ${base}).`);
}
EOF
