import { test } from 'node:test';
import assert from 'node:assert/strict';
import { makeRepo, cleanup, git, writeFiles } from '../../../../../engine-tests/helpers.mjs';
import { judge, resolveBefore } from '../pack-delivery-on-main.mjs';

const manifest = (version) => `export default {\n  id: 'demo',\n  version: '${version}',\n  minEngineVersion: 3,\n};\n`;
const log = (...versions) => `# Version history\n\n| Version | Date | What changed |\n|---|---|---|\n`
  + versions.map((v) => `| ${v} | 2026-08-30 | Demo. |\n`).join('');
const pack = (version, rules) => ({
  'packs/demo/pack.mjs': manifest(version),
  'packs/demo/VERSIONS.md': log(version),
  'packs/demo/RULES.md': rules,
});

const commit = (root, files, msg = 'more Refs #1') => {
  writeFiles(root, files);
  git(root, 'add', '-A');
  git(root, 'commit', '-q', '-m', msg);
};

test('content landing on main under the version main already published is the collision', () => {
  const root = makeRepo({
    base: pack('60830.5', '# Demo\n'),
    changed: { 'packs/demo/RULES.md': '# Demo\n\n- A rule the other branch never saw.\n' },
  });
  try {
    const { findings } = judge(root);
    assert.equal(findings.length, 1);
    assert.equal(findings[0].file, 'packs/demo/pack.mjs');
    assert.match(findings[0].what, /leaves its version at 60830\.5/);
  } finally { cleanup(root); }
});

test('content landing with its own version is what delivery looks like', () => {
  const root = makeRepo({
    base: pack('60830.5', '# Demo\n'),
    changed: {
      'packs/demo/RULES.md': '# Demo\n\n- A rule.\n',
      'packs/demo/pack.mjs': manifest('60830.6'),
      'packs/demo/VERSIONS.md': log('60830.6', '60830.5'),
    },
  });
  try { assert.deepEqual(judge(root).findings, []); } finally { cleanup(root); }
});

// A push is not always one commit, and the question is what the PUSH delivered.
test('the push\'s own base is judged, not just the last commit of it', () => {
  const root = makeRepo({ base: pack('60830.5', '# Demo\n') });
  const before = git(root, 'rev-parse', 'HEAD').trim();
  commit(root, {
    'packs/demo/RULES.md': '# Demo\n\n- One.\n',
    'packs/demo/pack.mjs': manifest('60830.6'),
    'packs/demo/VERSIONS.md': log('60830.6', '60830.5'),
  });
  commit(root, { 'packs/demo/RULES.md': '# Demo\n\n- One.\n- Two.\n' });
  try {
    assert.equal(judge(root, { before }).findings.length, 0);   // the push delivered 60830.6
    assert.equal(judge(root).findings.length, 1);               // its last commit alone did not
  } finally { cleanup(root); }
});

test('an unresolvable before falls back to the parent rather than judging nothing', () => {
  const root = makeRepo({ base: pack('60830.5', '# Demo\n'), changed: { 'packs/demo/RULES.md': '# Demo\n\n- A rule.\n' } });
  try {
    assert.equal(resolveBefore(root, { before: '0'.repeat(40) }), 'HEAD^');
    assert.equal(judge(root, { before: '0'.repeat(40) }).findings.length, 1);
  } finally { cleanup(root); }
});

test('a first commit has no previous main to judge against', () => {
  const root = makeRepo({ base: pack('60830.5', '# Demo\n') });
  try {
    git(root, 'checkout', '-q', 'main');
    assert.equal(resolveBefore(root), null);
    assert.deepEqual(judge(root), { base: null, findings: [] });
  } finally { cleanup(root); }
});
EOF
node --test .claudinite/local/packs/canon-curation/test/pack-delivery-on-main.test.mjs 2>&1 | tail -12

