1	#!/usr/bin/env node
2	// THE WORK SCOPE'S CI ENTRY POINT — one command a project's test/CI flow runs to
3	// have this change judged, as check_the_world.mjs is for the tree.
4	//
5	// WHY A SCRIPT AND NOT EIGHT LINES OF YAML. Everything below is decided the same
6	// way in every repo, and each part is a way for the gate to look green while
7	// judging nothing:
8	//
9	//   THE BASE REF. A work scope with no base resolves to an EMPTY DIFF, and an
10	//   empty diff passes every rule silently. A CI checkout carries no
11	//   origin/<default> unless something fetches it, so this fetches it and fails
12	//   loudly when it cannot — never proceeds baseless.
13	//
14	//   THE AUTOMATION BRANCHES. A member's maintenance and update PRs are opened by
15	//   the engine on `claudinite/…` branches, with no session and no issue behind
16	//   them. Judged as work, they fail task-lifecycle for lacking a task they never
17	//   had — and since delivery arms auto-merge, which is a queue for CHECKS, a red
18	//   check there does not annoy anyone: it stops the repo updating, permanently
19	//   and quietly. So they are skipped, out loud.
20	//
21	//   THE PUSH ONTO THE BASE BRANCH. Sitting on the base branch used to mean
22	//   "nothing to judge", and on a developer's clone it does. In CI it is a PUSH
23	//   EVENT — a merge landing — and that is the one place two branches that each
24	//   moved a shared number are visible at once, so it is the only place a rule
25	//   about the change can see them collide (#1482). Judged against what the
26	//   branch held BEFORE the push, it is an ordinary work scope.
27	//
28	//   THE EMPTY SCOPE. The runner prints nothing on a clean sweep and nothing on a
29	//   sweep that judged nothing. This prints the scope either way, so a green step
30	//   says what it actually looked at.
31	//
32	// Living in engine/ is what makes it a fleet mechanism rather than a recipe:
33	// the engine root vendors wholesale on every converge, so a member's workflow
34	// carries one invocation that never changes, and this logic converges to every
35	// member the moment it changes here.
36	//
37	//   node .claudinite/shared/engine/checks/ci-work-scope.mjs     (a member)
38	//   node engine/checks/ci-work-scope.mjs                        (the canon home)
39	//
40	// Options: --root DIR (default cwd), --branch NAME (default: the checkout's
41	// branch — CI checks out a detached head, so a workflow passes it explicitly).
42	import { spawnSync } from 'node:child_process';
43	import { readFileSync } from 'node:fs';
44	import { dirname, join } from 'node:path';
45	import { fileURLToPath } from 'node:url';
46	import { BASE_REF_CANDIDATES } from './helpers/repo-context.mjs';
47	
48	const HERE = dirname(fileURLToPath(import.meta.url));
49	export const RUNNER = join(HERE, 'check_the_work.mjs');
50	
51	// The prefix the engine opens its own PRs under (update, maintenance, and every
52	// generated-artifact delivery). Named here rather than matched loosely: a repo's
53	// own branch called "claudinite-something" is a person's branch and is judged.
54	export const AUTOMATION_PREFIX = 'claudinite/';
55	
56	export const isAutomationBranch = (branch) => (branch ?? '').startsWith(AUTOMATION_PREFIX);
57	
58	const git = (root, ...args) => {
59	  const r = spawnSync('git', args, { cwd: root, encoding: 'utf8' });
60	  return r.status === 0 ? (r.stdout ?? '').trim() : null;
61	};
