79	// when this is not a push in CI. `GITHUB_EVENT_PATH` is the payload GitHub
80	// Actions writes for every event and names in the environment unasked, so a
81	// member's workflow needs no new input to reach it — this converges with the
82	// engine and starts working. `before` is absent outside a push and all-zero on a
83	// branch's first push; `HEAD^` covers those and a manual re-run, and a root
84	// commit has neither.
85	const ZERO_SHA = /^0+$/;
