116	  if (!changed.length) {
117	    return { run: false, code: 1, say: `work scope: no diff against ${base} — the sweep would judge nothing and pass` };
118	  }
119	  return { run: true, code: 0, base, changed, say: `work scope: ${changed.length} changed file(s) vs ${base}` };
120	}
